mapper.update:
UPDATE ai_decision_record 
SET is_deleted = 1, update_time = NOW() 
WHERE id = #{id}

mapper.select:
SELECT r.id, r.decision_no AS decisionNo, r.decision_type AS decisionType, r.business_type AS businessType, r.business_id AS businessId, r.confidence, r.priority, r.status, r.auto_execute AS autoExecute, r.handled_by AS handledBy, a.name AS handlerName, r.create_time AS createTime, r.handle_time AS handleTime FROM ai_decision_record r LEFT JOIN admin_info a ON r.handled_by = a.id WHERE r.is_deleted = 0
AND r.decision_type = #{query.decisionType}
AND r.status = #{query.status}
AND r.priority = #{query.priority}
AND r.business_type = #{query.businessType}
AND r.create_time >= #{query.startTime}
AND r.create_time <= #{query.endTime}
ORDER BY r.priority DESC, r.create_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM ai_decision_record r
WHERE r.is_deleted = 0

    AND r.decision_type = #{query.decisionType}


    AND r.status = #{query.status}


    AND r.priority = #{query.priority}


    AND r.business_type = #{query.businessType}


    AND r.create_time >= #{query.startTime}


    AND r.create_time <= #{query.endTime}
